function shortDescriptionFor(brandName: string, categoryName: string) {
  return brandName === "Sin Marca" ? categoryName : `${brandName} · ${categoryName}`;
}

function descriptionFor(name: string, brandName: string) {
  const brandPart = brandName === "Sin Marca" ? "" : ` de ${brandName}`;
  return `${name}${brandPart}. Disponible en Core Market — consultanos por WhatsApp si querés más información antes de comprar.`;
}

async function main() {
  console.log("Sembrando catálogo real de Core Market...");

  const categoryMap = new Map<string, string>();
  for (const c of categories) {
    const created = await db.category.upsert({
      where: { slug: c.slug },
      update: {
        name: c.name,
        description: c.description,
        image: `https://picsum.photos/id/${CATEGORY_PHOTOS[c.slug][0]}/1200/900`,
        position: c.position,
      },
      create: {
        slug: c.slug,
        name: c.name,
        description: c.description,
        image: `https://picsum.photos/id/${CATEGORY_PHOTOS[c.slug][0]}/1200/900`,
        position: c.position,
      },
    });
    categoryMap.set(c.slug, created.id);
  }

  const brandMap = new Map<string, string>();
  for (const b of REAL_BRANDS) {
    const created = await db.brand.upsert({
      where: { slug: b.slug },
      update: { name: b.name, logo: `https://picsum.photos/seed/brand-${b.slug}/200/200` },
      create: {
        slug: b.slug,
        name: b.name,
        logo: `https://picsum.photos/seed/brand-${b.slug}/200/200`,
      },
    });
    brandMap.set(b.slug, created.id);
  }

  let count = 0;
  for (const p of REAL_PRODUCTS) {
    const categoryId = categoryMap.get(p.categorySlug);
    const brandId = brandMap.get(p.brandSlug);
    if (!categoryId || !brandId) {
      throw new Error(`Missing category/brand for product ${p.slug} (${p.categorySlug}/${p.brandSlug})`);
    }
    const brandName = REAL_BRANDS.find((b) => b.slug === p.brandSlug)!.name;
    const categoryName = categories.find((c) => c.slug === p.categorySlug)!.name;
    const featured = FEATURED_SLUGS.includes(p.slug);

    const realImages = REAL_PRODUCT_IMAGES[p.slug];
    const images = realImages
      ? realImages.map((url, i) => ({ url, alt: p.name, position: i }))
      : [0, 1].map((i) => img(CATEGORY_PHOTOS[p.categorySlug][i], p.name, i));

    const sharedFields = {
      sku: p.sku,
      name: p.name,
      shortDescription: shortDescriptionFor(brandName, categoryName),
      description: descriptionFor(p.name, brandName),
      price: p.price,
      stock: p.stock,
      tags: p.tags,
      featured,
      categoryId,
      brandId,
    };

    await db.product.upsert({
      where: { slug: p.slug },
      update: {
        ...sharedFields,
        images: { deleteMany: {}, create: images },
      },
      create: {
        slug: p.slug,
        ...sharedFields,
        images: { create: images },
      },
    });
    count++;
  }

  // Clean up leftover products from earlier demo catalogs (pre-real-catalog
  // seeds). Only remove ones with no order history, so we never touch data
  // tied to a real purchase.
  await db.product.deleteMany({
    where: {
      slug: { notIn: REAL_PRODUCTS.map((p) => p.slug) },
      orderItems: { none: {} },
    },
  });

  await db.brand.deleteMany({
    where: {
      slug: { notIn: REAL_BRANDS.map((b) => b.slug) },
      products: { none: {} },
    },
  });

  // Only delete categories left with zero products — if a demo product with
  // real order history is still holding one, leave it in place instead of
  // failing the whole deploy.
  const staleCategories = await db.category.findMany({
    where: { slug: { notIn: categories.map((c) => c.slug) } },
    select: { id: true, _count: { select: { products: true } } },
  });
  const deletableCategoryIds = staleCategories
    .filter((c) => c._count.products === 0)
    .map((c) => c.id);
  if (deletableCategoryIds.length > 0) {
    await db.category.deleteMany({ where: { id: { in: deletableCategoryIds } } });
  }

  console.log(
    `Listo: ${categories.length} categorías, ${REAL_BRANDS.length} marcas, ${count} productos.`,
  );
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await db.$disconnect();
  });
